<div class="page-heading"><div><span class="eyebrow">WORKSPACE HISTORY</span><h1>Activity</h1><p>The latest 200 recorded changes.</p></div></div><div class="table-wrap"><table><thead><tr><th>Event</th><th>Details</th><th>By</th><th>Time (UTC)</th></tr></thead><tbody><?php foreach($events as $event): ?><tr><td><code><?= e($event['action']) ?></code></td><td><?= e($event['description']) ?></td><td><?= e($event['name']) ?></td><td class="nowrap"><?= e($event['created_at']) ?></td></tr><?php endforeach ?><?php if(!$events): ?><tr><td colspan="4"><div class="empty-state"><h3>A fresh start</h3><p>Your workspace activity will appear here.</p></div></td></tr><?php endif ?></tbody></table></div>
